import local.prominence.hourglass.Balance;import elocindev.prominentbase.mythicchallenge.*;public class HourglassBehaviorChecks {static void eq(double a,double b){if(Math.abs(a-b)>0.00001)throw new AssertionError(a+" != "+b);} public static void main(String[] x){var c=new MythicScalingConfig();for(int level:new int[]{1,15,16,30})for(int n=1;n<=5;n++){var b=new MythicBossEntry();Balance.spawn(b,null,null,level,5,n);double base=level*100.0;eq(b.hp,base*.8*(1+.8*(n-1)));eq(b.hp/Balance.factor(n),base*.8);if(Balance.inBossSpawn())throw new AssertionError("scope leak");}eq(Balance.bossHp(c,16,1,5,1),8000);var bad=new MythicBossEntry();bad.fail=true;try{Balance.spawn(bad,null,null,16,5,2);throw new AssertionError("no failure");}catch(IllegalStateException ok){}if(Balance.inBossSpawn())throw new AssertionError("exception scope leak");System.out.println("PASS: 20 level/party combinations, independent add baseline, fallback and exception-safe scope");}}